const body = $input.first().json.body;
const invalid = (mensaje, status = 400) => [{ json: { status, tipo: 'error', mensaje } }];
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  return invalid('Envía la solicitud como JSON.');
}

const text = body.message ?? body.chatInput ?? body.text;
const session = body.sessionId ?? body.session_id;
if (typeof text !== 'string' || !text.trim()) return invalid('Escribe un mensaje para continuar.');
if (text.length > 4000) return invalid('El mensaje puede tener hasta 4.000 caracteres.', 413);
if (typeof session !== 'string' || !/^[A-Za-z0-9_-]{8,128}$/.test(session)) {
  return invalid('Inicia una conversación nueva y vuelve a enviar tu mensaje.');
}

return [{ json: { message: text.trim(), sessionId: session, valid: true } }];

// ID del calendario que recibe las citas y correo interno del equipo.
const calendarId = '';
const teamEmail = '';
return [{ json: { ...$input.first().json, calendarId, teamEmail } }];

const original = $input.first().json.output;
const request = $('Validar solicitud').first().json;
const result = (tipo, mensaje, rest = {}) => [{ json: { tipo, mensaje, ...rest } }];
const badOutput = () => result('error', 'No pude preparar la respuesta. Vuelve a enviar tu mensaje.', { status: 502 });
const text = (value, max = 300) => typeof value === 'string' ? value.trim().slice(0, max) : '';
const emailValid = /^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]+$/;
const services = {
  1: ['Gestión Pro', 'Te ayuda a preparar el RUP y el perfil en SECOP II para participar en procesos de contratación pública.'],
  2: ['Entrenamiento Pro', 'Te orienta en MGA Web y las plataformas del Sistema General de Regalías para formular y gestionar proyectos.'],
  3: ['Entrenamiento Pro', 'Tu equipo puede capacitarse en plataformas oficiales y metodologías de gestión como PMI y SCRUM.'],
  4: ['Estratégica Pro', 'Puedes trabajar con el equipo en software a la medida, gestión de proyectos y fortalecimiento institucional.'],
  5: ['Diagnóstico y asesoría integral 360°', 'El equipo puede revisar tu situación y ayudarte a priorizar los siguientes pasos.'],
};

let parsed;
try {
  const json = typeof original === 'string'
    ? original.trim().replace(/^```(?:json)?\s*([\s\S]*?)\s*```$/i, '$1')
    : original;
  parsed = typeof json === 'string' ? JSON.parse(json) : json;
} catch {
  return badOutput();
}
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return badOutput();

if (parsed.tipo === 'mensaje') {
  const mensaje = text(parsed.mensaje, 6000);
  return mensaje ? result('mensaje', mensaje) : badOutput();
}

const data = parsed.datos ?? {};
const nit = text(data.nit, 20);
const sector = text(data.sector);
const objetivo = text(data.objetivo);
const service = services[text(String(data.objetivo_codigo), 10)];
if (!/^\d{6,10}(?:-\d)?$/.test(nit) || !sector || !objetivo || !Array.isArray(service)) {
  return result('mensaje', 'Me falta confirmar el NIT, el sector o el objetivo. ¿Puedes revisar esos datos?');
}
const [servicio_recomendado, recommendation] = service;
const common = { nit, sector, objetivo, servicio_recomendado };

if (parsed.tipo === 'diagnostico_final') {
  const sizes = { micro: 'Micro', pequeña: 'Pequeña', mediana: 'Mediana', grande: 'Grande' };
  const tamano = sizes[text(data.tamano).toLowerCase()];
  if (typeof tamano !== 'string' || typeof data.contrato_previo !== 'boolean') {
    return result('mensaje', '¿Me confirmas el tamaño de tu empresa y si ya ha contratado con el Estado?');
  }
  const contrato_previo = data.contrato_previo ? 'Sí' : 'No';
  const nivel_madurez = !data.contrato_previo
    ? 'Inicial'
    : ['Micro', 'Pequeña'].includes(tamano) ? 'Intermedio' : 'Avanzado';
  const summary = (value) => value.replace(/\s+/g, ' ').replace(/[*_`\[\]<>]/g, '');
  const mensaje = [
    '**Diagnóstico de Madurez Empresarial**',
    '',
    `- **NIT:** ${nit}`,
    `- **Sector:** ${summary(sector)}`,
    `- **Tamaño:** ${tamano}`,
    `- **Objetivo:** ${summary(objetivo)}`,
    `- **Experiencia previa con el Estado:** ${contrato_previo}`,
    `- **Nivel de madurez:** ${nivel_madurez}`,
    '',
    `**Servicio recomendado:** ${servicio_recomendado}. ${recommendation}`,
    '',
    '¿Quieres agendar una cita con el equipo de IDEAPRO para revisar el diagnóstico?',
  ].join('\n');
  const datos = {
    ...common, tamano, contrato_previo, nivel_madurez,
    respuesta_sector: text(data.respuesta_sector) || null,
  };
  return result('diagnostico_final', mensaje, { datos });
}

if (parsed.tipo !== 'agendar_cita') return badOutput();
const nombre_contacto = text(data.nombre_contacto, 120);
const correo_contacto = text(data.correo_contacto, 255);
if (!nombre_contacto) return result('mensaje', '¿Cuál es el nombre de la persona que asistirá?');
if (correo_contacto.length > 254 || !emailValid.test(correo_contacto)) {
  return result('mensaje', '¿Me confirmas tu correo electrónico de contacto?');
}

const fecha = text(data.fecha, 20);
const hora = text(data.hora, 12);
if (!/^\d{2}\/\d{2}\/\d{4}$/.test(fecha)) {
  return result('mensaje', 'Escribe la fecha de la cita con el formato DD/MM/AAAA.');
}
const fecha_iso = fecha.split('/').reverse().join('-');
const day = new Date(`${fecha_iso}T00:00:00Z`);
if (!Number.isFinite(day.getTime()) || day.toISOString().slice(0, 10) !== fecha_iso) {
  return result('mensaje', 'Esa fecha no existe. Escribe otra fecha en formato DD/MM/AAAA.');
}
if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(hora) || request.message !== hora) {
  return result('mensaje', `Escribe solo la hora que prefieres para el ${fecha} en formato HH:MM, por ejemplo 10:00.`);
}

const start = new Date(`${fecha_iso}T${hora}:00-05:00`);
if (start.getTime() <= Date.now()) {
  return result('mensaje', 'Esa fecha y hora ya pasaron. Escribe una fecha futura para la cita en formato DD/MM/AAAA.');
}
const datos = { ...common, nombre_contacto, correo_contacto, fecha, fecha_iso, hora };
return result('agendar_cita', '', {
  datos,
  start: start.toISOString(),
  end: new Date(start.getTime() + 60 * 60 * 1000).toISOString(),
});

return [{ json: {
  tipo: 'mensaje',
  mensaje: 'Ese horario está ocupado. ¿Qué otra fecha te queda bien? Escríbela en formato DD/MM/AAAA.',
} }];

