const { fecha, hora } = $('Verificar respuesta').first().json.datos;
const event = $input.first().json;
return [{ json: {
  tipo: 'agendar_cita',
  mensaje: `Tu cita con IDEAPRO quedó agendada para el **${fecha} a las ${hora}** (hora de Colombia). Duración: **1 hora**.`,
  eventLink: typeof event.htmlLink === 'string' ? event.htmlLink : null,
} }];

const { datos } = $('Verificar respuesta').first().json;
const risk = { Inicial: 'Alto', Intermedio: 'Medio', Avanzado: 'Bajo' };
const aviso = [
  'Nuevo diagnóstico de madurez empresarial',
  `NIT: ${datos.nit}`,
  `Sector: ${datos.sector}`,
  `Tamaño: ${datos.tamano}`,
  `Objetivo: ${datos.objetivo}`,
  `Experiencia con el Estado: ${datos.contrato_previo}`,
  `Madurez: ${datos.nivel_madurez}`,
  `Nivel de preparación orientativo: ${risk[datos.nivel_madurez]}`,
  `Servicio recomendado: ${datos.servicio_recomendado}`,
];
return [{ json: { aviso: aviso.join('\n') } }];

